# Re-enable Network Throttling Index Write-Host "Re-enabling network throttling index..." -ForegroundColor Cyan # Reset NetworkThrottlingIndex to default (10 = 0xA) Set-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" -Name "NetworkThrottlingIndex" -Value 10 -Type DWord -Force -ErrorAction SilentlyContinue # Reset SystemResponsiveness to default (20) Set-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" -Name "SystemResponsiveness" -Value 20 -Type DWord -Force -ErrorAction SilentlyContinue Write-Host "Network throttling has been re-enabled (default values)." -ForegroundColor Green